INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES ("2025/12/21 12:00:00", 0, 1, 0, 0, "みやこ", "【物理】中衛で、味方をプリンで強化する幽霊聖少女。\n物理攻撃力と物理クリティカルアップのプリンパワーの\nフィールドで自分のスキルも強化し、猛攻を繰り出す。", 1, 1, 302, 0, 3, "2025/12/31 11:59:59", 119901, 450, 0, 119901, 0, 2.17, 119901, 1, 119901, "ミヤコ（クリスマス）", 14, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES ("2026/03/16 10:00:00", 0, 5, 0, 0, "しずる", "【物理】前衛で猛攻から味方を守護する闇のお姉ちゃん。\nバトル開始時の行動不能無効スキルで周囲の味方を守り、\n範囲を束縛するスキルで敵を牽制し、戦況を一変する。", 5, 1, 190, 0, 3, "2026/03/31 11:59:59", 120001, 450, 0, 120001, 0, 2.375, 120001, 1, 120001, "シズル（ノワール）", 6, 0);
